"""The persistent pseudonym: what it accepts, what it refuses, and what it means.

This is the one piece of the analytics design that deliberately reverses an
earlier decision — `visitor_hash` rotates nightly precisely so nobody can be
followed, and this follows them. What keeps that defensible is a short list of
properties, and each one has a test here:

* it is generated by the browser and never derived from the request, so
  clearing site data really does end it;
* anything not matching a v4 UUID exactly is discarded, because the header
  arrives on an unauthenticated public endpoint;
* what we store is a hash, so the value in the database is not the value in
  the browser;
* the daily pseudonym still counts people who send nothing, so opting out
  costs a retention number and not a headcount;
* only the person who PLANS a trip is recorded against it — never someone who
  opens a share link.
"""

from __future__ import annotations

import uuid
from datetime import datetime, timedelta

import pytest
import pytest_asyncio
from httpx import ASGITransport, AsyncClient
from sqlalchemy import func, select
from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker, create_async_engine

from app.core.database import Base, get_db
from app.core.visitor import client_hash, request_client_id
from app.main import app
from app.models import AppEvent, TripStat, Vehicle
from app.services.geo import RouteGeometry
from app.services.routing import RouteData
from app.services.simulator import ChargerNode
from app.services.usage import usage_stats
from tests.fixtures import nl_to_austria_route
from tests.test_api import BORN_SEED, plan_body, vehicle_id

CID = "3f2a1b4c-5d6e-4f70-8192-a3b4c5d6e7f8"
CID2 = "9e8d7c6b-5a49-4382-b716-0f1e2d3c4b5a"


def _request_with(header_value: str | None):
    """A bare Starlette request carrying (or not carrying) the header."""
    from starlette.requests import Request

    headers = []
    if header_value is not None:
        headers.append((b"x-client-id", header_value.encode()))
    return Request(
        {
            "type": "http",
            "method": "POST",
            "path": "/api/events",
            "headers": headers,
            "client": ("1.2.3.4", 1234),
        }
    )


class TestValidation:
    def test_a_v4_uuid_is_accepted(self):
        assert request_client_id(_request_with(CID)) == client_hash(CID)

    def test_case_is_normalised(self):
        """Some clients upper-case hex. The same browser must not become two
        people because of it."""
        assert request_client_id(_request_with(CID.upper())) == client_hash(CID)

    @pytest.mark.parametrize(
        "value",
        [
            None,
            "",
            "   ",
            "not-a-uuid",
            "3f2a1b4c5d6e4f708192a3b4c5d6e7f8",          # no dashes
            "3f2a1b4c-5d6e-1f70-8192-a3b4c5d6e7f8",      # v1, not v4
            "3f2a1b4c-5d6e-4f70-0192-a3b4c5d6e7f8",      # bad variant nibble
            "3f2a1b4c-5d6e-4f70-8192-a3b4c5d6e7f8x",     # trailing junk
            "'; DROP TABLE app_events; --",
            "x" * 5000,
        ],
    )
    def test_anything_else_is_discarded(self, value):
        """The header is hostile input on a public endpoint. A caller must not
        be able to write a string of their choosing into the database."""
        assert request_client_id(_request_with(value)) is None

    def test_the_stored_value_is_not_the_browsers_value(self):
        """If an id ever leaks into a URL or a screenshot, it must not be
        usable to go looking for that person's rows."""
        assert client_hash(CID) != CID
        assert CID not in client_hash(CID)
        assert len(client_hash(CID)) == 32

    def test_it_does_not_rotate(self):
        """The opposite of `visitor_hash`, on purpose — this is the whole
        feature. If it ever starts rotating, retention silently reads zero."""
        assert client_hash(CID) == client_hash(CID)

    def test_different_browsers_differ(self):
        assert client_hash(CID) != client_hash(CID2)


